saveItem:(session,key,input,itemId)=>command(session,key,'item.save:'+itemId,input,async(t,u,control)=>{const p=itemInput.parse(input),{reason,version,sellingPrice,...record}=p;let saved=itemId;
   if(control.entry_version===2){record.selling_price=sellingPrice===null||sellingPrice===undefined||sellingPrice===''?null:money(price(sellingPrice,'sellingPrice'));if(!itemId&&p.code!==undefined)fieldError('code','Item codes are generated automatically.','ITEM_CODE_READ_ONLY');}
   else if(!p.code)fieldError('code','Item code is required for this preserved V1 setup.');
   if(itemId){const old=await t('v1_items').where({id:itemId}).first();if(!old||old.version!==version)fail('STALE_RECORD');if(p.code!==undefined&&old.code!==p.code)fieldError('code','A saved item code cannot be changed.','ITEM_CODE_IMMUTABLE');record.code=old.code;await t('v1_items').where({id:itemId}).update({...record,version:version+1});}
   else{if(control.entry_version===2){let next=BigInt(control.next_item_code);do{if(next>999999999999n)fail('ITEM_CODE_EXHAUSTED');record.code='ITM-'+String(next).padStart(4,'0');next++;}while(await t('v1_items').where({code:record.code}).first());await t('v1_control').where({id:1}).update({next_item_code:next.toString()});}[saved]=await t('v1_items').insert({...record,version:1});await t('v1_stock').insert({item_id:saved,quantity:'0',verified:false});}
   await audit(t,u,'item.saved',saved,`Item ${itemId?'updated':'created'}; version ${version||0} -> ${version?version+1:1}${reason?'; operator note: '+reason:''}`);return {id:String(saved),code:record.code};})

saveItem:(session,key,input,itemId)=>command(session,key,'item.save:'+itemId,input,async(t,u,control)=>{const p=itemInput.parse(input),{reason,version,sellingPrice,...record}=p;let saved=itemId;
   if(control.entry_version===2){record.selling_price=sellingPrice===null||sellingPrice===undefined||sellingPrice===''?null:money(price(sellingPrice,'sellingPrice'));if(!itemId&&p.code!==undefined)fieldError('code','Item codes are generated automatically.','ITEM_CODE_READ_ONLY');}
   else if(!p.code)fieldError('code','Item code is required for this preserved V1 setup.');
   if(itemId){const old=await t('v1_items').where({id:itemId}).first();if(!old||old.version!==version)fail('STALE_RECORD');if(p.code!==undefined&&old.code!==p.code)fieldError('code','A saved item code cannot be changed.','ITEM_CODE_IMMUTABLE');record.code=old.code;await t('v1_items').where({id:itemId}).update({...record,version:version+1});}
   else{if(control.entry_version===2){let next=BigInt(control.next_item_code);do{if(next>999999999999n)fail('ITEM_CODE_EXHAUSTED');record.code='ITM-'+String(next).padStart(4,'0');next++;}while(await t('v1_items').where({code:record.code}).first());await t('v1_control').where({id:1}).update({next_item_code:next.toString()});}[saved]=await t('v1_items').insert({...record,version:1});await t('v1_stock').insert({item_id:saved,quantity:'0',verified:false});}
   await audit(t,u,'item.saved',saved,`Item ${itemId?'updated':'created'}; version ${version||0} -> ${version?version+1:1}${reason?'; operator note: '+reason:''}`);return {id:String(saved),code:record.code};})

async function post(t,u,control,d){
  if(d.status!=='DRAFT')fail('IMMUTABLE_DOCUMENT');const p=d.payload;if(p.date>today())fail('FUTURE_DATE_NOT_ALLOWED',400);if(p.kind==='CHALLAN'&&!validLocalTime(p.time))fieldError('time','Choose a valid local time in HH:mm format.','INVALID_LOCAL_TIME');
  if(p.kind==='CHALLAN_RETURN')return postReturn(t,u,d);
  let party=null,total=0n,saleDiscount=null;uniqueLines(p.lines);const entryV12=control.entry_version===2;const changes=new Map(),lines=[];
  if(['PURCHASE','CHALLAN','CLIENT_OPENING','VENDOR_OPENING','CLIENT_PAYMENT','VENDOR_PAYMENT','OPENING_CORRECTION'].includes(p.kind)){
   party=await t('v1_parties').where({id:p.partyId,active:true}).first();if(!party)fieldError('partyId','Please select an active client or vendor.','ACTIVE_PARTY_REQUIRED');const expected=['CHALLAN','CLIENT_OPENING','CLIENT_PAYMENT'].includes(p.kind)?'CLIENT':['PURCHASE','VENDOR_OPENING','VENDOR_PAYMENT'].includes(p.kind)?'VENDOR':party.kind;if(party.kind!==expected)fail('PARTY_KIND_MISMATCH',400);if(p.partySnapshot&&party.version!==p.partySnapshot.version)fail('PARTY_CHANGED_REVIEW_DRAFT');
  }
  if(['PURCHASE','CLIENT_PAYMENT','VENDOR_PAYMENT'].includes(p.kind)){
   const reference=(p.reference||p.chequeReference||'').trim().toLowerCase();if(!reference&&p.kind==='PURCHASE')fail('TRANSACTION_REFERENCE_REQUIRED',400);
   const existing=await t('v1_documents').where({kind:p.kind,party_id:p.partyId,status:'POSTED'});
   if(existing.some(row=>{const old=JSON.parse(row.payload);return Boolean(reference&&(old.reference||old.chequeReference||'').trim().toLowerCase()===reference)||Boolean(p.method==='CHEQUE_RECEIVED'&&p.chequeReference&&old.method==='CHEQUE_RECEIVED'&&old.chequeReference.trim().toLowerCase()===p.chequeReference.trim().toLowerCase());}))fail('DUPLICATE_TRANSACTION_REFERENCE');
  }
  if(['STOCK_OPENING','PRODUCTION','PURCHASE','CHALLAN','STOCK_CORRECTION'].includes(p.kind)){
   if(!p.lines.length)fail('BOTTLE_LINES_REQUIRED',400);if(p.kind==='STOCK_OPENING'&&p.lines.length!==1)fail('ONE_ITEM_OPENING_REQUIRED',400);
   for(const [index,l]of p.lines.entries()){
    const item=await t('v1_items').where({id:l.itemId,active:true}).first();if(!item)fail('ACTIVE_BOTTLE_REQUIRED',400);if(l.expectedVersion&&item.version!==l.expectedVersion)fail('BOTTLE_CHANGED_REVIEW_DRAFT');
    const quantity=integer(l.quantity,{signed:p.kind==='STOCK_CORRECTION',zero:p.kind==='STOCK_OPENING'});if(p.kind==='STOCK_CORRECTION'&&quantity===0n)fail('NONZERO_CORRECTION_REQUIRED',400);
    if(entryV12&&p.kind==='CHALLAN'){if(!item.selling_price)fieldError(`lines.${index}.itemId`,'Price not set. Set an approved selling price in Item Management before posting.','PRICE_NOT_SET');if(!l.pricingVersion||l.pricingVersion!==item.version||price(l.rate,`lines.${index}.rate`)!==price(item.selling_price,`lines.${index}.rate`))fieldError(`lines.${index}.rate`,'Price changed. Edit the draft and explicitly refresh pricing.','PRICE_CHANGED');}
    const rate=['PURCHASE','CHALLAN'].includes(p.kind)?cents(l.rate,{zero:!(entryV12&&p.kind==='CHALLAN')}):0n,amount=quantity*rate;total+=amount;money(total);
    const delta=p.kind==='CHALLAN'?-quantity:quantity;changes.set(String(item.id),(changes.get(String(item.id))||0n)+delta);
    lines.push({document_id:d.id,line_no:index+1,item_id:item.id,snapshot:JSON.stringify({description:item.description,quality:item.quality,colour:item.colour,packing:item.packing,code:item.code}),quantity:quantity.toString(),rate:money(rate),amount:money(amount)});
   }
   for(const [itemId,delta]of [...changes].sort((a,b)=>BigInt(a[0])<BigInt(b[0])?-1:1)){
    const stock=await t('v1_stock').where({item_id:itemId}).forUpdate().first();if(!stock)fail('STOCK_PROJECTION_MISSING');
    if(p.kind==='STOCK_OPENING'){if(stock.verified)fail('DUPLICATE_STOCK_OPENING');await t('v1_stock').where({item_id:itemId}).update({verified:true});}
    else if(!stock.verified)fail('STOCK_OPENING_UNVERIFIED');else{const opening=await t('v1_stock_journal as j').join('v1_documents as d','d.id','j.document_id').where({'j.item_id':itemId,'d.kind':'STOCK_OPENING','d.status':'POSTED'}).select('d.date').first();if(!opening||p.date<opening.date)fail('DATE_PRECEDES_STOCK_OPENING',400);}
    const journalRows=await t('v1_stock_journal').where({item_id:itemId});if(journalRows.reduce((n,j)=>n+integer(j.delta,{signed:true}),0n)!==BigInt(stock.quantity))fail('STOCK_RECONCILIATION_REQUIRED');const next=integer(stock.quantity,{zero:true})+delta;if(next<0n)fieldError(`lines.${p.lines.findIndex(l=>l.itemId===itemId)}.quantity`,`Only ${stock.quantity} bottles are available.`,'INSUFFICIENT_STOCK',{itemId,available:stock.quantity});integer(next.toString(),{zero:true});
    await t('v1_stock').where({item_id:itemId}).update({quantity:next.toString()});await t('v1_stock_journal').insert({document_id:d.id,item_id:itemId,delta:delta.toString()});
   }
   await t('v1_lines').insert(lines);
  }else if(p.lines.length)fail('UNEXPECTED_BOTTLE_LINES',400);
  if(['CLIENT_OPENING','VENDOR_OPENING'].includes(p.kind)){
   if(party.opening_verified)fail('DUPLICATE_PARTY_OPENING');if(!p.direction)fail('OPENING_DIRECTION_REQUIRED',400);total=cents(p.amount,{zero:true});
   await journal(t,d,party,p.direction==='OWED_TO_COMPANY'?total:0n,p.direction==='OWED_BY_COMPANY'?total:0n,'Explicit '+party.kind.toLowerCase()+' opening');await t('v1_parties').where({id:party.id}).update({opening_verified:true});
  }else if(['CHALLAN','PURCHASE','CLIENT_PAYMENT','VENDOR_PAYMENT'].includes(p.kind)){
   if(!party.opening_verified)fail('PARTY_OPENING_UNVERIFIED');const opening=await t('v1_documents').where({party_id:party.id,status:'POSTED'}).whereIn('kind',['CLIENT_OPENING','VENDOR_OPENING']).first();if(!opening||p.date<opening.date)fail('DATE_PRECEDES_OPENING',400);
   if(p.kind==='CHALLAN'){if(entryV12){saleDiscount=discount(total,p.discountMode,p.discountValue);if(JSON.stringify(p.discountSummary)!==JSON.stringify(saleDiscount))fieldError('discountValue','Review and save this draft with its current subtotal and discount.','DISCOUNT_REVIEW_REQUIRED');total=cents(saleDiscount.total);}
    await journal(t,d,party,total,0n,'Delivery challan sale');}
   if(p.kind==='PURCHASE'){await journal(t,d,party,p.paidImmediately?total:0n,total,p.paidImmediately?'Bottle purchase paid immediately; method reference only':'Bottle purchase payable');if(p.paidImmediately&&(!p.method||p.method==='CHEQUE_RECEIVED'||!p.reference))fail('IMMEDIATE_PAYMENT_METHOD_AND_REFERENCE_REQUIRED',400);}
   if(['CLIENT_PAYMENT','VENDOR_PAYMENT'].includes(p.kind)){total=cents(p.amount);if(!p.method||p.kind==='VENDOR_PAYMENT'&&p.method==='CHEQUE_RECEIVED')fail('PAYMENT_METHOD_REQUIRED',400);if(p.method==='CHEQUE_RECEIVED'&&!p.chequeReference)fail('CHEQUE_REFERENCE_REQUIRED',400);await journal(t,d,party,p.kind==='VENDOR_PAYMENT'?total:0n,p.kind==='CLIENT_PAYMENT'?total:0n,p.kind==='CLIENT_PAYMENT'?'Amount received · '+p.method:'Amount paid · '+p.method);}
  }else if(p.kind==='EXPENSE'){
   if(!p.category||!p.description||!p.payee||!p.reference||p.paymentStatus!=='PAID'||!['CASH','BANK_TRANSFER'].includes(p.method)||p.partyId)fail('PAID_EXPENSE_DETAILS_REQUIRED',400);total=cents(p.amount);
  }else if(p.kind==='PAYMENT_REVERSAL'){
   const source=await t('v1_documents').where({id:p.correctsId,status:'POSTED'}).first();if(!source||!['CLIENT_PAYMENT','VENDOR_PAYMENT'].includes(source.kind)||p.date<source.date)fail('INVALID_PAYMENT_REVERSAL',400);if(source.kind==='CLIENT_PAYMENT'&&JSON.parse(source.payload).method!=='CHEQUE_RECEIVED')fail('ONLY_CHEQUE_DISHONOUR_SUPPORTED',400);party=await t('v1_parties').where({id:source.party_id}).first();total=cents(source.total);await journal(t,d,party,source.kind==='CLIENT_PAYMENT'?total:0n,source.kind==='VENDOR_PAYMENT'?total:0n,'Traceable payment reversal');
  }else if(p.kind==='STOCK_CORRECTION'){
   const source=await t('v1_documents').where({id:p.correctsId,status:'POSTED'}).first();if(!source||!['STOCK_OPENING','PRODUCTION','STOCK_CORRECTION'].includes(source.kind)||p.date<source.date)fail('ONLY_NONFINANCIAL_STOCK_CORRECTION_SUPPORTED',400);const itemIds=await t('v1_lines').where({document_id:source.id}).pluck('item_id');if([...changes.keys()].some(k=>!itemIds.map(String).includes(k)))fail('CORRECTION_ITEM_MISMATCH',400);
  }else if(p.kind==='OPENING_CORRECTION'){
   const source=await t('v1_documents').where({id:p.correctsId,party_id:party.id,status:'POSTED'}).first();if(!source||!['CLIENT_OPENING','VENDOR_OPENING','OPENING_CORRECTION'].includes(source.kind)||!p.direction||p.date<source.date)fail('INVALID_OPENING_CORRECTION',400);
   if(await t('v1_documents').where({party_id:party.id,status:'POSTED'}).whereNotIn('kind',['CLIENT_OPENING','VENDOR_OPENING','OPENING_CORRECTION']).first())fail('OPENING_CORRECTION_AFTER_ACTIVITY_BLOCKED');
   const previous=await t('v1_party_journal').where({party_id:party.id}),balance=previous.reduce((n,r)=>n+cents(r.debit,{zero:true})-cents(r.credit,{zero:true}),0n);total=cents(p.amount,{zero:true});const target=p.direction==='OWED_TO_COMPANY'?total:-total,delta=target-balance;await journal(t,d,party,delta>0n?delta:0n,delta<0n?-delta:0n,'Reviewed replacement opening; prior evidence retained');
  }
  let number=['CLIENT_PAYMENT','VENDOR_PAYMENT'].includes(p.kind)?paymentNumber(p.kind,d.id):null,sequence=null;if(p.kind==='CHALLAN'){sequence=control.next_dc;number=dcNumber(sequence);await t('v1_control').where({id:1}).update({next_dc:sequence+1});}
  await t('v1_documents').where({id:d.id,version:d.version,status:'DRAFT'}).update({status:'POSTED',total:money(total),...(saleDiscount?{sale_subtotal:saleDiscount.subtotal,discount_mode:saleDiscount.mode,discount_value:saleDiscount.value,discount_amount:saleDiscount.amount}:{}),party_id:party?.id||null,official_number:number,sequence,corrects_id:p.correctsId||null});await audit(t,u,'document.posted',number||d.id,p.reason);return {id:String(d.id),status:'POSTED',official_number:number,total:money(total)};
 }

async list(session,name,search=''){
      const r=resource(name);
      return identity.read(session,r.read,async trx=>{
        let builder=trx(r.table).select('*').orderBy('code').limit(100);
        if(search)builder=builder.where(q=>q.where('name','like',`%${search}%`).orWhere('code','like',`%${search}%`));
        const rows=await query(builder);
        // No balance/opening fields exist. Sales gets only customer contact/dispatch fields.
