async post(session,id,raw,key){const input=command.parse(raw);return run(session,'returns.read',`return.post:${id}`,key,input,async(trx,actor)=>{
  const doc=await load(trx,id);if(doc.status==='POSTED')fail('DUPLICATE_POSTING');if(doc.version!==input.version)fail('STALE_VERSION');const body=draftInput.parse(JSON.parse(doc.payload));if(payloadHash(body)!==doc.payload_hash)fail('RETURN_SOURCE_EVIDENCE_MISMATCH');const original=await verifySource(trx,body,doc),rows=await lines(trx,doc),normalized=await normalize(trx,body,original);if(rows.length!==normalized.length||rows.some((r,i)=>Object.entries(normalized[i]).some(([k,v])=>!same(r[k]??'',v??''))))fail('RETURN_SOURCE_EVIDENCE_MISMATCH');const policy=await accepted(trx,doc.business_date);let approval=null;if(doc.kind==='INSPECTION'){admin(actor);approval=await validateApproval(trx,session,id);const authority=await query(trx('user_roles as u').join('role_permissions as p','p.role_code','u.role_code').where({'u.user_id':approval.approver_id,'u.role_code':'administrator','p.permission_code':'returns.disposition.approve'}).first());if(!authority)fail('APPROVAL_AUTHORITY_REVOKED');}else if(doc.status!=='DRAFT')fail('INVALID_DOCUMENT_STATE');
  const [batch]=await query(trx('business_posting_batches').insert({document_id:id,document_version:doc.version,action:`RETURN_${doc.kind}`,created_at:now()}));
  if(doc.kind==='RECEIPT')for(const row of [...rows].sort((a,b)=>BigInt(a.sales_line_id)<BigInt(b.sales_line_id)?-1:1)){const sent=await query(trx('sales_lines').where({id:row.sales_line_id}).first());let allowance=await query(trx('return_allowances').where({sales_line_id:row.sales_line_id}).forUpdate().first());if(!allowance){await query(trx('return_allowances').insert({sales_line_id:row.sales_line_id,dispatched:sent.quantity,received:'0.000000',version:1}));allowance={dispatched:sent.quantity,received:'0.000000',version:1};}const allReceipts=await query(trx('return_receipts').where({sales_line_id:row.sales_line_id}));if(allReceipts.reduce((n,r)=>n+exact(r.quantity),0n)!==exact(allowance.received))fail('RETURN_ALLOWANCE_EVIDENCE_MISMATCH');const prior=await query(trx('return_receipts').where({request_line_id:row.request_line_id})),requestLine=await query(trx('return_lines').where({id:row.request_line_id}).first()),amount=exact(row.quantity);if(exact(allowance.dispatched)!==exact(sent.quantity)||exact(allowance.received)+amount>exact(sent.quantity)||prior.reduce((n,r)=>n+exact(r.quantity),0n)+amount>exact(requestLine.quantity))fail('RETURN_QUANTITY_EXCEEDED');if(await query(trx('return_allowances').where({sales_line_id:row.sales_line_id,version:allowance.version}).update({received:decimal(exact(allowance.received)+amount),version:(BigInt(allowance.version)+1n).toString()}))!==1)fail('STALE_RETURN_ALLOWANCE');await query(trx('return_receipts').insert({line_id:row.id,document_id:id,request_line_id:row.request_line_id,sales_line_id:row.sales_line_id,quantity:row.quantity,policy_id:policy.id,batch_id:batch,actor_id:actor.id,created_at:now()}));await query(trx('return_receipt_balances').insert({line_id:row.id,received:row.quantity,remaining:row.quantity,version:1}));}
  if(doc.kind==='INSPECTION'){const row=rows[0],b=await query(trx('return_receipt_balances').where({line_id:row.receipt_line_id}).forUpdate().first());if(Number(b.version)!==Number(row.expected_version)||b.remaining!==row.quantity)fail('STALE_RETURN_QUARANTINE');await query(trx('return_dispositions').insert({line_id:row.id,document_id:id,receipt_line_id:row.receipt_line_id,under_disposition:row.quantity,reusable:row.reusable,damaged:row.damaged,remaining:row.remaining,policy_id:policy.id,approval_id:approval.id,batch_id:batch,actor_id:actor.id,created_at:now()}));if(await query(trx('return_receipt_balances').where({line_id:b.line_id,version:b.version}).update({remaining:row.remaining,version:(BigInt(b.version)+1n).toString()}))!==1)fail('STALE_RETURN_QUARANTINE');}
  const movementCount=doc.kind==='REQUEST'?0:await stockEffects(trx,actor,doc,batch,rows,input.reason);await query(trx('business_documents').where({id}).update({status:'POSTED',updated_at:now()}));const {number}=await issueNumber(trx,actor,{documentId:id,businessDate:doc.business_date,policyId:policy.business_policy_id});await event(trx,actor,doc,'POSTED',input.reason,{batchId:String(batch),policyId:String(policy.id),movementCount,financialCreditProcessed:false});return {id,status:'POSTED',number,movementCount,financialCreditProcessed:false};
