async post(session,id,raw,key){const i=command.parse(raw);return run(session,'expenses.read',`expense.post:${id}`,key,i,async(trx,actor)=>{const d=await load(trx,id);if(d.status==='POSTED')fail('DUPLICATE_POSTING');if(d.version!==i.version)fail('STALE_VERSION');const {body,e}=await verified(trx,d),a=await approval(trx,session,d,e.approvalRequired,d.kind==='CORRECTION'?'expenses.correct.approve':'expenses.approve');if(d.kind==='CORRECTION')fail('EXPENSE_CORRECTION_EFFECTS_PENDING');const lines=await query(trx('expense_lines').where({document_id:id,document_version:d.version}).orderBy('line_index'));if(lines.length!==e.rows.length||lines.some((l,n)=>Object.entries(e.rows[n]).some(([k,v])=>!same(l[k],v))))fail('EXPENSE_LINE_EVIDENCE_MISMATCH');let plan=null;if(body.payment){plan=await paymentPlan(trx,d,body,e);const target=d.kind==='PAYMENT'?d.original_id:d.id;if(await query(trx('expense_payments').where({expense_id:target,external_reference:body.payment.instrumentReference}).first()))fail('DUPLICATE_EXPENSE_PAYMENT_REFERENCE');}
