 await query(trx('business_documents').where({id}).update({status:'POSTED',updated_at:now()}));const {number}=await issueNumber(trx,actor,{documentId:id,businessDate:d.business_date,policyId:e.policy.business_policy_id});await query(trx('business_document_events').insert({document_id:id,version:d.version,event:'POSTED',actor_id:actor.id,reason:i.reason,created_at:now()}));await businessAudit(trx,actor,'expense.posted','expenses',id,d.version,{reason:i.reason,batchId:String(batch),approvalId:a?String(a.id):null,total:body.total,paid:plan?money(plan.amount):'0.00'});return {id,status:'POSTED',number,expenseId:d.kind==='EXPENSE'?id:String(d.original_id),paid:plan?money(plan.amount):'0.00'};
 },async trx=>{const d=await load(trx,id),body=JSON.parse(d.payload);return d.kind==='CORRECTION'?['expenses.correct.post']:[d.kind==='EXPENSE'?'expenses.record':'expenses.pay',...(body.payment?['expenses.pay','money.transactions.post']:[])];});}
